body.script:
function korreou(e){
  if(e.dataset.correu){ e.href="mailto:"+atob(e.dataset.correu); delete e.dataset.correu; }
  return true;
}
function inicialitzaLector(){
  var boto = document.getElementById('btn-llegeix');
  if(!boto){ return; }
  if(!('speechSynthesis' in window)){ boto.hidden = true; return; }
  boto.hidden = false;
  var contingut = document.querySelector(boto.getAttribute('data-lector'));
  var blocs = [];
  var index = 0;
  var actiu = false;
  var etiqueta = boto.querySelector('.lector-btn-label');

  function textPlana(){
    if(!contingut){ return ''; }
    var clon = contingut.cloneNode(true);
    clon.querySelectorAll('script,style,svg').forEach(function(n){ n.parentNode.removeChild(n); });
    clon.querySelectorAll('a').forEach(function(n){
      n.parentNode.replaceChild(document.createTextNode(n.textContent), n);
    });
    clon.querySelectorAll('h1,h2,h3,h4,h5,h6,p,li,blockquote').forEach(function(n){
      n.textContent = n.textContent + '\n\n';
    });
    return clon.textContent;
  }
  function llegirBloc(){
    if(!actiu){ return; }
    if(index >= blocs.length){ aturaLectura(true); return; }
    var ut = new SpeechSynthesisUtterance(blocs[index]);
    ut.lang = 'ca-ES';
    ut.rate = 1;
    ut.onend = function(){ index++; llegirBloc(); };
    ut.onerror = function(){ index++; llegirBloc(); };
    window.speechSynthesis.speak(ut);
  }
  function aturaLectura(esborra){
    window.speechSynthesis.cancel();
    actiu = false;
    index = 0;
    boto.classList.remove('actiu');
    boto.setAttribute('aria-pressed', 'false');
    if(etiqueta){ etiqueta.textContent = boto.dataset.inici; }
  }
  function llegeix(){
    if(actiu){ aturaLectura(false); return; }
    blocs = textPlana().split(/\n{2,}/).map(function(s){ return s.trim(); }).filter(Boolean);
    if(!blocs.length){ return; }
    actiu = true;
    boto.classList.add('actiu');
    boto.setAttribute('aria-pressed', 'true');
    if(etiqueta){ etiqueta.textContent = boto.dataset.atura; }
    llegirBloc();
  }
  boto.addEventListener('click', llegeix);
  document.addEventListener('visibilitychange', function(){
    if(document.hidden && actiu){ window.speechSynthesis.cancel(); }
  });
  window.addEventListener('beforeunload', function(){ window.speechSynthesis.cancel(); });
}
document.addEventListener('DOMContentLoaded', inicialitzaLector);

(function(){
  var boto = document.getElementById('btn-torna-dalt');
  if(!boto){ return; }
  var CIRC = 2 * Math.PI * 22;
  var barra = boto.querySelector('.scroll-top-bar');
  boto.removeAttribute('hidden');
  function progress(){
    var max = document.documentElement.scrollHeight - window.innerHeight;
    var sc = window.scrollY || document.documentElement.scrollTop || 0;
    var pct = max > 0 ? sc / max : 0;
    if(pct >= 1){ pct = 1; }
    barra.style.strokeDashoffset = CIRC * (1 - pct);
    if(sc > 280){
      boto.classList.add('is-visible');
    } else {
      boto.classList.remove('is-visible');
    }
  }
  boto.addEventListener('click', function(){
    window.scrollTo({ top: 0, behavior: 'smooth' });
  });
  document.addEventListener('scroll', progress, { passive: true });
  window.addEventListener('resize', progress);
  progress();
})();

(function(){
  var btn = document.querySelector('.nav-toggle');
  var panel = document.getElementById('site-nav-panel');
  if(!btn || !panel){ return; }
  btn.addEventListener('click', function(){
    var isOpen = panel.classList.toggle('open');
    btn.setAttribute('aria-expanded', isOpen ? 'true' : 'false');
  });
  document.addEventListener('click', function(e){
    if(!btn.contains(e.target) && !panel.contains(e.target)){
      panel.classList.remove('open');
      btn.setAttribute('aria-expanded', 'false');
    }
  });
})();
